<section class="settings-group"><x-section-heading tag="h3" icon="users" tone="info">Account details</x-section-heading><x-setting-value label="Full name" :value="auth()->user()->name" /><x-setting-value label="Username" :value="auth()->user()->username" /><x-setting-value label="Role" :value="ucfirst(auth()->user()->role)" /><p>Ask a Manager to update your employee details or issue assisted recovery.</p><x-button variant="secondary" data-dialog-open="account-password">Change password</x-button></section><section class="settings-group"><x-section-heading tag="h3" icon="users" tone="info">Active sessions</x-section-heading><x-setting-value label="Saved sessions" :value="(string)$sessionCount" help="Your current session is retained when ending other sessions." /><x-button variant="secondary" data-dialog-open="account-sessions">End other sessions</x-button></section>
<x-dialog id="account-password" title="Change your password"><form method="post" action="{{ route('account.password') }}" class="stack" data-account-form>@csrf<x-input id="account-current-password" name="current_password" type="password" label="Current password" required autocomplete="current-password" /><x-input id="account-new-password" name="password" type="password" label="New password" required minlength="15" maxlength="1024" autocomplete="new-password" /><x-input id="account-confirm-password" name="password_confirmation" type="password" label="Confirm new password" required minlength="15" maxlength="1024" autocomplete="new-password" /><p>All sessions will end after the change. Sign in with your new password.</p><div class="action-row"><x-button variant="secondary" data-dialog-close>Cancel</x-button><x-button type="submit">Change and sign out</x-button></div></form></x-dialog>
<x-dialog id="account-sessions" title="End your other sessions?"><form method="post" action="{{ route('account.sessions') }}" class="stack" data-account-form>@csrf<p>Your current session stays signed in. Other sessions must sign in again.</p><x-input id="sessions-current-password" name="current_password" type="password" label="Current password" required autocomplete="current-password" /><div class="action-row"><x-button variant="secondary" data-dialog-close>Cancel</x-button><x-button type="submit">End other sessions</x-button></div></form></x-dialog>
